1	package com.example.starter.translation.service;
2	
3	import com.example.starter.translation.api.ApiDtos;
4	import com.example.starter.translation.api.ApiException;
5	import com.example.starter.translation.domain.Rows.ApprovalRow;
6	import com.example.starter.translation.domain.Rows.DocumentRow;
7	import com.example.starter.translation.domain.Rows.SegmentRow;
8	import com.example.starter.translation.domain.Rows.TermRuleRow;
9	import com.example.starter.translation.domain.Rows.TranslationRow;
10	import com.example.starter.translation.repo.TranslationRepository;
11	import com.fasterxml.jackson.databind.ObjectMapper;
12	import org.springframework.stereotype.Service;
13	import org.springframework.transaction.annotation.Transactional;
14	
15	import java.util.ArrayList;
16	import java.util.HashSet;
17	import java.util.LinkedHashMap;
18	import java.util.List;
19	import java.util.Locale;
20	import java.util.Map;
21	import java.util.Set;
22	import java.util.function.Function;
23	import java.util.stream.Collectors;
24	
25	/**
26	 * 多语种段落修订与发布快照的核心业务服务。
27	 * 所有写操作先对文档行加 FOR UPDATE 行锁，保证同一文档的修改、审核与发布串行，
28	 * 并发下对应一个一致的文档状态；方法均加入调用方事务，与幂等记录原子提交。
29	 */
30	@Service
31	public class TranslationService {
32	
33	    private final TranslationRepository repository;
34	    private final ObjectMapper objectMapper;
35	
36	    public TranslationService(TranslationRepository repository, ObjectMapper objectMapper) {
37	        this.repository = repository;
38	        this.objectMapper = objectMapper;
39	    }
40	
41	    /** 建文档：1~5 种目标语言，可携带初始段落，初始草稿版本 1、发布版本 0。 */
42	    @Transactional
43	    public ApiDtos.DocumentResponse createDocument(ApiDtos.CreateDocumentRequest request) {
44	        List<String> languages = normalizeLanguages(request.targetLanguages());
45	        List<ApiDtos.SegmentInput> segments = request.segments();
46	        long distinct = segments.stream().map(ApiDtos.SegmentInput::segmentId).distinct().count();
47	        if (distinct != segments.size()) {
48	            throw ApiException.unprocessable("初始段落 segmentId 重复");
49	        }
50	        long documentId = repository.insertDocument(languages);
51	        for (ApiDtos.SegmentInput segment : segments) {
52	            repository.insertSegment(documentId, segment.segmentId(), segment.sourceText());
53	        }
54	        return new ApiDtos.DocumentResponse(documentId, 1, 0, languages);
55	    }
56	
57	    /** 增加段落：segmentId 文档内唯一，草稿版本加一。 */
58	    @Transactional
59	    public ApiDtos.SegmentResponse addSegment(long documentId, ApiDtos.AddSegmentRequest request) {
60	        DocumentRow document = lockDocument(documentId);
61	        if (repository.findSegment(documentId, request.segmentId()).isPresent()) {
62	            throw ApiException.conflict("段落已存在: " + request.segmentId());
63	        }
64	        repository.insertSegment(documentId, request.segmentId(), request.sourceText());
65	        int draftVersion = bumpDraftVersion(document);
66	        return new ApiDtos.SegmentResponse(documentId, request.segmentId(), 1, draftVersion);
67	    }
68	
69	    /** 源文修订：源文版本加一、草稿版本加一；相关译文因源文版本落后而待更新。 */
70	    @Transactional
71	    public ApiDtos.SegmentResponse reviseSource(long documentId, String segmentId,
72	                                              ApiDtos.ReviseSourceRequest request) {
73	        DocumentRow document = lockDocument(documentId);
74	        SegmentRow segment = findSegmentOrThrow(documentId, segmentId);
75	        int sourceVersion = segment.sourceVersion() + 1;
76	        repository.updateSegmentSource(documentId, segmentId, request.sourceText(), sourceVersion);
77	        int draftVersion = bumpDraftVersion(document);
78	        return new ApiDtos.SegmentResponse(documentId, segmentId, sourceVersion, draftVersion);
79	    }
80	
81	    /**
82	     * 译文提交：所依据源文版本必须等于当前源文版本；绑定当前术语版本，
83	     * 当前源文命中的术语规则要求译文包含对应必译文本，否则 422 返回全部违规术语且不写译文；
84	     * 译文版本递增，草稿版本加一。
85	     */
86	    @Transactional
87	    public ApiDtos.TranslationResponse submitTranslation(long documentId, String segmentId, String language,
88	                                                         String actorId, ApiDtos.SubmitTranslationRequest request) {
89	        DocumentRow document = lockDocument(documentId);
90	        String normalizedLanguage = normalizeLanguage(language);
91	        if (!document.targetLanguages().contains(normalizedLanguage)) {
92	            throw ApiException.unprocessable("语言不在文档目标语言中: " + normalizedLanguage);
93	        }
94	        SegmentRow segment = findSegmentOrThrow(documentId, segmentId);
95	        if (request.sourceVersion() != segment.sourceVersion()) {
96	            throw ApiException.unprocessable("译文所依据的源文版本 " + request.sourceVersion()
97	                    + " 与当前源文版本 " + segment.sourceVersion() + " 不匹配");
98	        }
99	        List<TermRuleRow> termRules = repository.listTermRules(documentId, document.termVersion());
100	        List<ApiDtos.TermRuleView> violations = findViolations(
101	                segment.sourceText(), normalizedLanguage, request.content(), termRules);
102	        if (!violations.isEmpty()) {
103	            throw ApiException.termViolation("译文违反 " + violations.size() + " 条术语规则", violations);
104	        }
105	        int translationVersion = repository.findTranslation(documentId, segmentId, normalizedLanguage)
106	                .map(TranslationRow::translationVersion).orElse(0) + 1;
107	        repository.upsertTranslation(documentId, new TranslationRow(segmentId, normalizedLanguage,
108	                request.content(), actorId, segment.sourceVersion(), translationVersion, document.termVersion()));
109	        int draftVersion = bumpDraftVersion(document);
110	        return new ApiDtos.TranslationResponse(documentId, segmentId, normalizedLanguage,
111	                translationVersion, segment.sourceVersion(), document.termVersion(), draftVersion);
112	    }
113	
114	    /** 译文批准：审核人不得是作者，且必须同时匹配当前源文与译文版本。 */
115	    @Transactional
116	    public ApiDtos.ApprovalResponse approveTranslation(long documentId, String segmentId, String language,
117	                                                       String actorId, ApiDtos.ApproveTranslationRequest request) {
118	        lockDocument(documentId);
119	        String normalizedLanguage = normalizeLanguage(language);
120	        SegmentRow segment = findSegmentOrThrow(documentId, segmentId);
121	        TranslationRow translation = repository.findTranslation(documentId, segmentId, normalizedLanguage)
122	                .orElseThrow(() -> ApiException.notFound(
123	                        "译文不存在: " + segmentId + "/" + normalizedLanguage));
124	        if (translation.author().equals(actorId)) {
125	            throw ApiException.unprocessable("审核人不得是该译文作者");
126	        }
127	        if (translation.translationVersion() != request.translationVersion()) {
128	            throw ApiException.unprocessable("批准所针对的译文版本 " + request.translationVersion()
129	                    + " 与当前译文版本 " + translation.translationVersion() + " 不匹配");
130	        }
131	        if (translation.sourceVersion() != segment.sourceVersion()) {
132	            throw ApiException.unprocessable("译文基于源文版本 " + translation.sourceVersion()
133	                    + "，当前源文版本 " + segment.sourceVersion() + "，译文待更新，不能批准");
134	        }
135	        repository.upsertApproval(documentId, new ApprovalRow(segmentId, normalizedLanguage, actorId,
136	                segment.sourceVersion(), translation.translationVersion()));
137	        return new ApiDtos.ApprovalResponse(documentId, segmentId, normalizedLanguage, actorId,
138	                translation.translationVersion(), segment.sourceVersion());
139	    }
140	
141	    /**
142	     * 新增术语版本：expectedTermVersion 必须等于当前术语版本（不符 409）；
143	     * 规则 0~100 条、按 sourceTerm 与目标语言唯一、语言须在文档目标语言中（不符 422）。
144	     * 成功后术语版本加一（已有版本不可覆盖），草稿版本加一；术语快照与草稿版本同一事务提交。
145	     */
146	    @Transactional
147	    public ApiDtos.TermVersionResponse updateTerms(long documentId, ApiDtos.UpdateTermsRequest request) {
148	        DocumentRow document = lockDocument(documentId);
149	        if (document.termVersion() != request.expectedTermVersion()) {
150	            throw ApiException.conflict("术语版本冲突：当前术语版本 " + document.termVersion()
151	                    + "，与期望的 " + request.expectedTermVersion() + " 不一致");
152	        }
153	        List<TermRuleRow> rules = new ArrayList<>();
154	        Set<List<String>> seen = new HashSet<>();
155	        for (ApiDtos.TermRuleInput input : request.rules()) {
156	            String language = normalizeLanguage(input.language());
157	            if (!document.targetLanguages().contains(language)) {
158	                throw ApiException.unprocessable("术语规则语言不在文档目标语言中: " + language);
159	            }
160	            if (!seen.add(List.of(input.sourceTerm(), language))) {
161	                throw ApiException.unprocessable(
162	                        "术语规则重复: " + input.sourceTerm() + "/" + language);
163	            }
164	            rules.add(new TermRuleRow(input.sourceTerm(), language, input.requiredTranslation()));
165	        }
166	        int termVersion = document.termVersion() + 1;
167	        repository.insertTermVersion(documentId, termVersion);
168	        for (TermRuleRow rule : rules) {
169	            repository.insertTermRule(documentId, termVersion, rule);
170	        }
171	        repository.updateTermVersion(documentId, termVersion);
172	        int draftVersion = bumpDraftVersion(document);
173	        return new ApiDtos.TermVersionResponse(documentId, termVersion, rules.size(), draftVersion);
174	    }
175	
176	    /**
177	     * 发布：校验期望版本（不符 409），再校验全部段落在全部目标语言均有有效批准（缺译或审核失效 422）、
178	     * 译文绑定当前术语版本（过期 422）且满足当前术语规则（违规 422 并返回全部违规术语），
179	     * 全部通过后原子生成完整只读快照（固化术语版本与实际规则集）并递增发布版本；
180	     * 任何失败回滚，不产生部分快照。
181	     */
182	    @Transactional
183	    public ApiDtos.PublishResponse publish(long documentId, ApiDtos.PublishRequest request) {
184	        DocumentRow document = lockDocument(documentId);
185	        if (document.draftVersion() != request.expectedDraftVersion()
186	                || document.publishedVersion() != request.expectedPublishedVersion()) {
187	            throw ApiException.conflict("版本冲突：当前草稿版本 " + document.draftVersion()
188	                    + "、发布版本 " + document.publishedVersion() + "，与期望的 "
189	                    + request.expectedDraftVersion() + "/" + request.expectedPublishedVersion() + " 不一致");
190	        }
191	        List<SegmentRow> segments = repository.listSegments(documentId);
192	        Map<String, TranslationRow> translations = repository.listTranslations(documentId).stream()
193	                .collect(Collectors.toMap(t -> key(t.segmentId(), t.language()), Function.identity()));
194	        Map<String, ApprovalRow> approvals = repository.listApprovals(documentId).stream()
195	                .collect(Collectors.toMap(a -> key(a.segmentId(), a.language()), Function.identity()));
196	        List<TermRuleRow> termRules = repository.listTermRules(documentId, document.termVersion());
197	        List<ApiDtos.TermRuleView> termViolations = new ArrayList<>();
198	        for (SegmentRow segment : segments) {
199	            for (String language : document.targetLanguages()) {
200	                TranslationRow translation = translations.get(key(segment.segmentId(), language));
201	                if (translation == null) {
202	                    throw ApiException.unprocessable(
203	                            "缺少译文: " + segment.segmentId() + "/" + language);
204	                }
205	                if (translation.sourceVersion() != segment.sourceVersion()) {
206	                    throw ApiException.unprocessable("译文待更新: " + segment.segmentId() + "/" + language
207	                            + " 基于源文版本 " + translation.sourceVersion()
208	                            + "，当前源文版本 " + segment.sourceVersion());
209	                }
210	                if (translation.termVersion() != document.termVersion()) {
211	                    throw ApiException.unprocessable("译文术语版本过期: " + segment.segmentId() + "/" + language
212	                            + " 绑定术语版本 " + translation.termVersion()
213	                            + "，当前术语版本 " + document.termVersion());
214	                }
215	                ApprovalRow approval = approvals.get(key(segment.segmentId(), language));
216	                if (approval == null) {
217	                    throw ApiException.unprocessable(
218	                            "缺少批准: " + segment.segmentId() + "/" + language);
219	                }
220	                if (approval.translationVersion() != translation.translationVersion()
221	                        || approval.sourceVersion() != segment.sourceVersion()) {
222	                    throw ApiException.unprocessable("批准已失效: " + segment.segmentId() + "/" + language
223	                            + "，源文或译文版本已改变");
224	                }
225	                termViolations.addAll(findViolations(
226	                        segment.sourceText(), language, translation.content(), termRules));
227	            }
228	        }
229	        if (!termViolations.isEmpty()) {
230	            throw ApiException.termViolation("译文违反 " + termViolations.size() + " 条术语规则", termViolations);
231	        }
232	        int publishedVersion = document.publishedVersion() + 1;
233	        repository.insertSnapshot(documentId, publishedVersion,
234	                buildSnapshotJson(document, publishedVersion, segments, translations, approvals, termRules));
235	        repository.updatePublishedVersion(documentId, publishedVersion);
236	        return new ApiDtos.PublishResponse(documentId, publishedVersion);
237	    }
238	
239	    /** 查询指定发布版本的只读快照 JSON；不存在返回 404。 */
240	    @Transactional(readOnly = true)
241	    public String getRelease(long documentId, int publishedVersion) {
242	        repository.findDocument(documentId)
243	                .orElseThrow(() -> ApiException.notFound("文档不存在: " + documentId));
244	        return repository.findSnapshot(documentId, publishedVersion)
245	                .orElseThrow(() -> ApiException.notFound(
246	                        "发布版本不存在: " + documentId + "/" + publishedVersion));
247	    }
248	
249	    /** 查询当前术语版本及完整规则集；尚未建立术语版本时返回版本 0 与空规则。 */
250	    @Transactional(readOnly = true)
251	    public ApiDtos.TermVersionView getCurrentTerms(long documentId) {
252	        DocumentRow document = repository.findDocument(documentId)
253	                .orElseThrow(() -> ApiException.notFound("文档不存在: " + documentId));
254	        return new ApiDtos.TermVersionView(documentId, document.termVersion(),
255	                toRuleViews(repository.listTermRules(documentId, document.termVersion())));
256	    }
257	
258	    /** 查询指定术语版本的不可变规则集；版本不存在返回 404。 */
259	    @Transactional(readOnly = true)
260	    public ApiDtos.TermVersionView getTerms(long documentId, int termVersion) {
261	        repository.findDocument(documentId)
262	                .orElseThrow(() -> ApiException.notFound("文档不存在: " + documentId));
263	        if (termVersion < 1 || !repository.termVersionExists(documentId, termVersion)) {
264	            throw ApiException.notFound("术语版本不存在: " + documentId + "/" + termVersion);
265	        }
266	        return new ApiDtos.TermVersionView(documentId, termVersion,
267	                toRuleViews(repository.listTermRules(documentId, termVersion)));
268	    }
269	
270	    /**
271	     * 查询全部译文的术语状态：绑定术语版本、是否相对当前术语版本过期，
272	     * 以及按当前源文与当前术语规则判定的违规术语（无违规为空列表）。
273	     */
274	    @Transactional(readOnly = true)
275	    public ApiDtos.TermStatusResponse getTermStatus(long documentId) {
276	        DocumentRow document = repository.findDocument(documentId)
277	                .orElseThrow(() -> ApiException.notFound("文档不存在: " + documentId));
278	        Map<String, SegmentRow> segments = repository.listSegments(documentId).stream()
279	                .collect(Collectors.toMap(SegmentRow::segmentId, Function.identity()));
280	        List<TermRuleRow> termRules = repository.listTermRules(documentId, document.termVersion());
281	        List<ApiDtos.TranslationTermStatus> statuses = new ArrayList<>();
282	        for (TranslationRow translation : repository.listTranslations(documentId)) {
283	            SegmentRow segment = segments.get(translation.segmentId());
284	            List<ApiDtos.TermRuleView> violations = segment == null ? List.of()
285	                    : findViolations(segment.sourceText(), translation.language(),
286	                            translation.content(), termRules);
287	            statuses.add(new ApiDtos.TranslationTermStatus(translation.segmentId(), translation.language(),
288	                    translation.translationVersion(), translation.termVersion(),
289	                    translation.termVersion() != document.termVersion(), violations));
290	        }
291	        return new ApiDtos.TermStatusResponse(documentId, document.termVersion(), statuses);
292	    }
293	
294	    private DocumentRow lockDocument(long documentId) {
295	        return repository.findDocumentForUpdate(documentId)
296	                .orElseThrow(() -> ApiException.notFound("文档不存在: " + documentId));
297	    }
298	
299	    private SegmentRow findSegmentOrThrow(long documentId, String segmentId) {
300	        return repository.findSegment(documentId, segmentId)
301	                .orElseThrow(() -> ApiException.notFound("段落不存在: " + segmentId));
302	    }
303	
304	    private int bumpDraftVersion(DocumentRow document) {
305	        int draftVersion = document.draftVersion() + 1;
306	        repository.updateDraftVersion(document.documentId(), draftVersion);
307	        return draftVersion;
308	    }
309	
310	    private static String key(String segmentId, String language) {
311	        return segmentId + "�" + language;
312	    }
313	
314	    private static String normalizeLanguage(String language) {
315	        return language.trim().toLowerCase(Locale.ROOT);
316	    }
317	
318	    private static List<String> normalizeLanguages(List<String> languages) {
319	        List<String> normalized = languages.stream().map(TranslationService::normalizeLanguage).distinct().toList();
320	        if (normalized.size() != languages.size()) {
321	            throw ApiException.unprocessable("目标语言重复");
322	        }
323	        return normalized;
324	    }
325	
326	    /**
327	     * 术语违规判定：源文按 Unicode 原文、区分大小写做连续子串匹配；仅源文命中 sourceTerm 的规则参与校验，
328	     * 译文正文（同样区分大小写）不含 requiredTranslation 即为违规。返回全部违规规则。
329	     */
330	    private static List<ApiDtos.TermRuleView> findViolations(String sourceText, String language, String content,
331	                                                             List<TermRuleRow> rules) {
332	        List<ApiDtos.TermRuleView> violations = new ArrayList<>();
333	        for (TermRuleRow rule : rules) {
334	            if (rule.language().equals(language) && sourceText.contains(rule.sourceTerm())
335	                    && !content.contains(rule.requiredTranslation())) {
336	                violations.add(toRuleView(rule));
337	            }
338	        }
339	        return violations;
340	    }
341	
342	    private static List<ApiDtos.TermRuleView> toRuleViews(List<TermRuleRow> rules) {
343	        return rules.stream().map(TranslationService::toRuleView).toList();
344	    }
345	
346	    private static ApiDtos.TermRuleView toRuleView(TermRuleRow rule) {
347	        return new ApiDtos.TermRuleView(rule.sourceTerm(), rule.language(), rule.requiredTranslation());
348	    }
349	
350	    /** 生成完整只读快照 JSON：全部段落源文及各语言译文、作者、审核人、版本号与固化的术语版本及规则集。 */
351	    private String buildSnapshotJson(DocumentRow document, int publishedVersion, List<SegmentRow> segments,
352	                                     Map<String, TranslationRow> translations,
353	                                     Map<String, ApprovalRow> approvals, List<TermRuleRow> termRules) {
354	        Map<String, Object> snapshot = new LinkedHashMap<>();
355	        snapshot.put("documentId", document.documentId());
356	        snapshot.put("publishedVersion", publishedVersion);
357	        snapshot.put("draftVersion", document.draftVersion());
358	        snapshot.put("termVersion", document.termVersion());
359	        snapshot.put("targetLanguages", document.targetLanguages());
360	        List<Map<String, Object>> termList = new ArrayList<>();
361	        for (TermRuleRow rule : termRules) {
362	            Map<String, Object> termJson = new LinkedHashMap<>();
363	            termJson.put("sourceTerm", rule.sourceTerm());
364	            termJson.put("language", rule.language());
365	            termJson.put("requiredTranslation", rule.requiredTranslation());
366	            termList.add(termJson);
367	        }
368	        snapshot.put("terms", termList);
369	        List<Map<String, Object>> segmentList = new ArrayList<>();
370	        for (SegmentRow segment : segments) {
371	            Map<String, Object> segmentJson = new LinkedHashMap<>();
372	            segmentJson.put("segmentId", segment.segmentId());
373	            segmentJson.put("sourceText", segment.sourceText());
374	            segmentJson.put("sourceVersion", segment.sourceVersion());
375	            List<Map<String, Object>> translationList = new ArrayList<>();
376	            for (String language : document.targetLanguages()) {
