loadFreezeEntries (group rows):

```java
/** 加载冻结条目并按术语与语言分组（行已按术语、语言、允许译法排序，分组后保持有序）。 */
private List<FreezeEntry> loadFreezeEntries(long documentId, int freezeVersion) {
    List<TermFreezeEntryRow> rows = repository.listTermFreezeEntries(documentId, freezeVersion);
    Map<List<String>, List<String>> grouped = new LinkedHashMap<>();
    for (TermFreezeEntryRow row : rows) {
        grouped.computeIfAbsent(List.of(row.sourceTerm(), row.language()), k -> new ArrayList<>())
                .add(row.allowedTranslation());
    }
    List<FreezeEntry> entries = new ArrayList<>();
    grouped.forEach((key, allowed) -> entries.add(new FreezeEntry(key.get(0), key.get(1), allowed)));
    return entries;
}
